        }
        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
        if (noNamesakes) {
            points += 1;
        }
        boolean largeHousehold = householdMemberCount != null && householdMemberCount >= 3;
        if (largeHousehold) {
            points += 2;
